local a={}local function b(c)return c[1][1]*(c[2][2]*c[3][3]-c[2][3]*c[3][2])-c[1][2]*(c[2][1]*c[3][3]-c[2][3]*c[3][1])+c[1][3]*(c[2][1]*c[3][2]-c[2][2]*c[3][1])end;function a.solve(d)if type(d)~="table"or#d<4 then return nil end;local e,f=d[1].pos,d[1].dist;local g=e.x*e.x+e.y*e.y+e.z*e.z;local h,i={},{}for j=2,4 do local k,l=d[j].pos,d[j].dist;h[j-1]={2*(k.x-e.x),2*(k.y-e.y),2*(k.z-e.z)}local m=k.x*k.x+k.y*k.y+k.z*k.z;i[j-1]=m-g-(l*l-f*f)end;local n=b(h)if math.abs(n)<1e-9 then return nil end;local function o(p)local c={{h[1][1],h[1][2],h[1][3]},{h[2][1],h[2][2],h[2][3]},{h[3][1],h[3][2],h[3][3]}}c[1][p],c[2][p],c[3][p]=i[1],i[2],i[3]return c end;return{x=b(o(1))/n,y=b(o(2))/n,z=b(o(3))/n}end;return a